#!/usr/bin/env bash
# Build gdansk-light (bootloader and/or Zigbee app) with the slt-managed
# toolchain, via the cmake/ninja projects generated by slc.
#
#   ./build.sh                 # generate (if needed) + build both
#   ./build.sh bootloader|app  # just one
#   REGEN=1 ./build.sh app     # force slc re-generation first
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
# slt and slc on PATH, or point SLT / SLC at them.
SLT="${SLT:-slt}"
SLC="${SLC:-slc}"
PART=EFR32MG21A020F768IM32

SDK="$($SLT where simplicity-sdk)"
export ARM_GCC_DIR="$($SLT where gcc-arm-none-eabi)"
export NINJA_EXE_PATH="$($SLT where ninja)/ninja"
export POST_BUILD_EXE="$(command -v commander)"
CMAKE="$($SLT where cmake)/bin/cmake"

build_one() {
  local dir="$1" slcp="$2"
  cd "$HERE/$dir"
  if [[ ! -d cmake_gcc || "${REGEN:-0}" == 1 ]]; then
    "$SLC" generate -p "$slcp" -d . -s "$SDK" --with "$PART" -o cmake -cpproj -tlcn gcc
  fi
  cd cmake_gcc
  "$CMAKE" --workflow --preset project
}

targets=("${@:-bootloader app}")
for t in ${targets[@]}; do
  case "$t" in
    bootloader) build_one bootloader gdansk_light_bootloader.slcp ;;
    app)        build_one app gdansk_light.slcp ;;
    *) echo "unknown target: $t" >&2; exit 1 ;;
  esac
done
